function UIOverseaTowerEntryDialog:StartTimeDown()
    if not isNull(self._timeDown) then
        CDTimerModule.GetInstance():RemoveCD(self._timeDown)
        self._timeDown = nil
    end

    self._timeDown = CDTimerModule.GetInstance():AddCD(1, function(count, id)
        local time = TowerQuestComponent:GetHookTime()
        if time >= 8 * 3600 then
            KTool.SetActive(self.CommonRedPoint.gameObject, true)
            CfUtils.FillText(self.TextNumber, string.format_color_tag(CfUtils.GetTimeHMS(8 * 3600), "#FFDD62"))
        else
            KTool.SetActive(self.CommonRedPoint.gameObject, false)
            CfUtils.FillText(self.TextNumber, CfUtils.GetTimeHMS(time))
            self:FillBox()
        end
    end, CountDownTime, false, true)
end

function UIOverseaTowerEntryDialog:FillBox()
    local time = TowerQuestComponent:GetHookTime()
    local canDrawReward = self:IsHaveRewards(time)
    local status = 1
    if canDrawReward and time <= 4 * 3600 then
        status = 2
    elseif canDrawReward and time > 4 * 3600 and time < 8 * 3600 then
        status = 3
    elseif canDrawReward and time >= 8 * 3600 then
        status = 4
    end
    CfUtils.SetActive(self.FirstPeriod, status == 2)
    CfUtils.SetActive(self.SecondPeriod, status == 3)
    CfUtils.SetActive(self.ThirdPeriod, status == 4)
    if status == 4 then
        CfUtils.SetActive(self.BoxCollect, false)
        CfUtils.SetActive(self.BoxCollectFull, true)
    elseif status == 1 then
        CfUtils.SetActive(self.BoxCollect, false)
        CfUtils.SetActive(self.BoxCollectFull, false)
    else
        CfUtils.SetActive(self.BoxCollect, true)
        CfUtils.SetActive(self.BoxCollectFull, false)
    end
end

function UIOverseaTowerEntryDialog:IsHaveRewards(hookTime)
    local id = OverseaTowerUtils.GetCurQuestId(Constants.TowerType.Main)
    local canDraw = false
    ---@type TowerQuestVo
    local questVo = OverseaTowerUtils.GetTowerQuestVo(id)
    if questVo then
        local rewardVo = RewardConfMgr:GetInstance():GetQuestRewardVo(id)
        if rewardVo then
            local t = checkTable(rewardVo.revenueRewardsTime)
            local _t = OverseaTowerUtils.GetAllReward()
            local minTime = 0
            for k, _ in pairs(t) do
                if checkNumber(_t[k].time) >= minTime then
                    minTime = checkNumber(_t[k].time)
                end
            end
            canDraw = checkNumber(hookTime) > minTime
        end
    end
    return canDraw
end

function UIOverseaTowerEntryDialog:FillCollectInfo()
    local isUnlock, des = OverseaTowerUtils.IsUnlockCollect()
    CfUtils.SetActive(self.Lock, not isUnlock)
    CfUtils.SetActive(self.Unlock, isUnlock)
    local collectUnlockTrans = self.BgNode.transform:Find("UIFX_Bg/TowerCollect_Unlock")
    if collectUnlockTrans then
        CfUtils.SetActive(collectUnlockTrans, isUnlock)
    end
    if isUnlock then
        local isFull = OverseaTowerUtils.IsMaxCollect()
        CfUtils.SetUISwitchImage(self.ImgReceive, isFull and 2 or 1)
        local time = TowerQuestComponent:GetHookTime()
        KTool.SetActive(self.CommonRedPoint.gameObject, time >= 8 * 3600)
        if time >= 8 * 3600 then
            CfUtils.FillText(self.TextNumber, string.format_color_tag(CfUtils.GetTimeHMS(8 * 3600), "#FFDD62"))
        else
            CfUtils.FillText(self.TextNumber, CfUtils.GetTimeHMS(time))
        end

        self:FillBox()
    else
        CfUtils.FillText(self.TextLock, des)
    end
end

