function UIOverseaTowerEntryDialog:FillMainTowerInfo()
    local isUnlock = true

    local id = OverseaTowerUtils.GetCurQuestId(Constants.TowerType.Main)
    local vo = OverseaTowerUtils.GetTowerQuestVo(id)
    if vo then
        CfUtils.FillText(self.TextNumberShadow2, vo.storey)
        CfUtils.FillText(self.TextNumber2, vo.storey)
        CfUtils.FillText(self.TextNumber3, vo.storey)
        ---刷新小猫层的数字
        local shadowTextNumber3 = self.TextNumberShadow2.transform.parent:Find("NumberOfFloorShadow/TextNumber3")
        if shadowTextNumber3 then
            CfUtils.FillText(shadowTextNumber3, vo.storey)
        end
        local animationId = math.floor(checkNumber(vo.storey) % 5)
        if animationId == 0 then
            animationId = 5
        end
        local catFloorNumberTrans = self.MainTower:Find("BgRed/FloorNumber")
        if catFloorNumberTrans then
            for i = 1, 5 do
                local textTrans = catFloorNumberTrans:Find("TextNumber" .. i)
                if i < animationId then
                    CfUtils.FillText(textTrans, checkNumber(vo.storey) - (animationId - i))
                elseif i == animationId then
                    --CfUtils.FillText(textTrans, checkNumber(vo.storey))
                    CfUtils.FillText(textTrans, '')
                else
                    CfUtils.FillText(textTrans, checkNumber(vo.storey) + (i - animationId))
                end
            end
        end

        CfUtils.PlayAnimation(self.MainTower, string.format('OverseaTowerEntryDialog_MainTower_Floor_%d', animationId))
    end
   
    CfUtils.IsDuoLeInVisiable(self.RankListShow)
    ---添加主塔的排名列表
    self:FillMainTowerRankInfo()
    local BgFxTrans = self.Container.transform:Find("UIFX_Tower_BG")
    local floorLevel = checkNumber(vo.storey)
    local status = 300
    if  floorLevel > 300 and floorLevel <= 600 then
        status = 600
    elseif floorLevel > 600 and floorLevel <= 900 then
        status = 900
    elseif floorLevel > 900 then
        status = 900
    end
    CfUtils.SetActive(BgFxTrans, floorLevel > 300)
    if floorLevel > 300 then
        CfUtils.PlayAnimation(BgFxTrans, 'OverseaTowerEntryDialog_UIFX_Tower_' .. status)
    end
end

function UIOverseaTowerEntryDialog:UpdateDots()
    local curNearestItemIndex = self.RankListShow.CurSnapNearestItemIndex
    if curNearestItemIndex < 0 or curNearestItemIndex > self.pageMax then
        return
    end
    if curNearestItemIndex > #self.dots then
        return
    end
    for i = 1, #self.dots do
        local go = self.dots[i]
        if i == (curNearestItemIndex + 1) then
            CfUtils.SetUISwitchImage(go, 2)
        else
            CfUtils.SetUISwitchImage(go, 1)
        end
    end
end

function UIOverseaTowerEntryDialog:OnSnapNearestChanged(listView, item)
    ---update dots
    self:UpdateDots()
end
---FillMainTowerRankInfo
---主塔排名的显示逻辑
function UIOverseaTowerEntryDialog:FillMainTowerRankInfo()
    local ranks = TowerQuestComponent:GetRankList(Constants.TowerType.Main)
    self.ranks = ranks
    self.pageMax = #ranks
    self.dots = {}
    KTool.DestroyGameObjectChildren(self.PageGroup.gameObject, false)
    for _ = 1, self.pageMax do
        local go = KTool.Instantiate(self.PageGroup.gameObject, self.ImgPage.gameObject, false)
        KTool.SetActive(go, true)
        table.insert(self.dots, go)
    end
    self:UpdateDots()
    ---表情包的界面的刷新的逻辑
    if not self.RankListShow.IsListViewInit then
        local initParam = CS.SuperScrollView.LoopListViewInitParam.CopyDefaultInitParam()
        initParam.mSnapVecThreshold = 99999
        --self.RankListShow.mOnBeginDragAction = OnBeginDrag
        --self.RankListShow.mOnDragingAction = OnDraging
        self.RankListShow.mOnEndDragAction = Bind(self, self.OnEndDrag)
        self.RankListShow.mOnSnapNearestChanged = Bind(self, self.OnSnapNearestChanged)
        self.RankListShow:InitListView(self.pageMax, Bind(self, self.OnGetItemByIndex), initParam)
    else
        GameUtils.ReloadData(self.RankListShow, self.pageMax)
    end
end

function UIOverseaTowerEntryDialog:OnGetItemByIndex(listView, index, item)
    if index < 0 then
        return nil
    end
    local pageNo = index + 1
    local cell = listView:NewListViewItem("Cell")
    local data = self.ranks[pageNo]
    ---@type TowerRankCellNode
    local env = CfUtils.GetLuaScr(cell.gameObject, TowerRankCellNodePath)
    if env then
        env:FreshUI(data, pageNo, function(towerType, payerInfo)
            ---点击回调
            self:OnRankButtonAction(towerType)
        end)
    end
    return cell
end

function UIOverseaTowerEntryDialog:OnEndDrag()
    local vec = self.RankListShow.ScrollRect.velocity.x
    local curNearestItemIndex = self.RankListShow.CurSnapNearestItemIndex
    local item = self.RankListShow:GetShownItemByItemIndex(curNearestItemIndex)
    if isNull(item) then
        self.RankListShow:ClearSnapData()
        return
    end
    if Mathf.Abs(vec) < 50 then
        self.RankListShow:SetSnapTargetItemIndex(curNearestItemIndex)
        return
    end
    local pos = self.RankListShow:GetItemCornerPosInViewPort(item, CS.SuperScrollView.ItemCornerEnum.LeftTop)
    if pos.x > 0 then
        if vec > 0 then
            self.RankListShow:SetSnapTargetItemIndex(curNearestItemIndex - 1)
        else
            self.RankListShow:SetSnapTargetItemIndex(curNearestItemIndex)
        end
    elseif pos.x < 0 then
        if vec > 0 then
            self.RankListShow:SetSnapTargetItemIndex(curNearestItemIndex)
        else
            self.RankListShow:SetSnapTargetItemIndex(curNearestItemIndex + 1)
        end
    else
        if vec > 0 then
            self.RankListShow:SetSnapTargetItemIndex(curNearestItemIndex - 1)
        else
            self.RankListShow:SetSnapTargetItemIndex(curNearestItemIndex + 1)
        end
    end
end

