function UIOverseaTowerEntryDialog:FillLeftInfo()
    local vo = OverseaTowerUtils.GetClimbTowerConfigVo(6)
    if not vo then
        return
    end

    --local isUnlock = true--OverseaTowerUtils.IsPassQuest(vo.num)
    local isUnlock = OverseaTowerUtils.IsPassQuest(vo.num)
    local configVo = OverseaTowerUtils.GetClimbTowerConfigVo(11)
    local lockBgCollect = self.BgNode.transform:Find("TowerCollect_Lock")
    CfUtils.SetActive(self.Container.transform:Find("AuxiliaryTower/Title"), isUnlock)
    CfUtils.SetActive(self.Container.transform:Find("AuxiliaryTower/Lock"), not isUnlock)
    if configVo then
        local isUnlockVo = OverseaTowerUtils.IsPassQuest(configVo.num)
        if lockBgCollect then
            KTool.SetActive(lockBgCollect.gameObject, not isUnlockVo)
        end
        local parVo = OverseaTowerUtils.GetClimbTowerConfigVo(5)
        CfUtils.FillText(self.Container.transform:Find("AuxiliaryTower/Lock/Layout/Layout/TextDesc"), localize('通关_num_层解锁', { _num_ = parVo.num }))
    else
        KTool.SetActive(lockBgCollect.gameObject, false)
    end

    local unlockContentGrow = self.UnlockContent.transform:Find("UIFX_Tower_Glow")
    if unlockContentGrow then
        KTool.SetActive(unlockContentGrow.gameObject, not isUnlock)
    end
    CfUtils.SetActive(self.UnlockContent, isUnlock)
    CfUtils.SetActive(self.ImgLock, not isUnlock)
    local unlockTrans = self.ImgLock.transform.parent:Find("Unlock")
    if unlockTrans then
        CfUtils.SetActive(unlockTrans, isUnlock)
    end
    CfUtils.SetUISwitchImage(self.Container.transform:Find("AuxiliaryTower/Lock/ImgBg"), isUnlock and 2 or 1)

    ---解锁后处理排行榜人头像信息的逻辑
    local ranks = TowerQuestComponent:GetRankList(Constants.TowerType.Red)
    local playerInfoTrans = self.RedTower:Find("PlayerInfo")
    if playerInfoTrans then
        CfUtils.SetActive(playerInfoTrans, #ranks > 0)
        if #ranks > 0 then
            local playerInfo = table.takeFirst(ranks)
            self:FreshRankHeadNode(playerInfoTrans, playerInfo, function()
                self:OnRankButtonAction(Constants.TowerType.Red)
            end)
        end
    end
    ---解锁后处理排行榜人头像信息的逻辑
    ranks = TowerQuestComponent:GetRankList(Constants.TowerType.Green)
    playerInfoTrans = self.GreenTower:Find("PlayerInfo")
    if playerInfoTrans then
        CfUtils.SetActive(playerInfoTrans, #ranks > 0)
        if #ranks > 0 then
            local playerInfo = table.takeFirst(ranks)
            self:FreshRankHeadNode(playerInfoTrans, playerInfo, function()
                self:OnRankButtonAction(Constants.TowerType.Green)
            end)
        end
    end
    ---解锁后处理排行榜人头像信息的逻辑
    ranks = TowerQuestComponent:GetRankList(Constants.TowerType.Blue)
    playerInfoTrans = self.BlueTower:Find("PlayerInfo")
    if playerInfoTrans then
        CfUtils.SetActive(playerInfoTrans, #ranks > 0)
        if #ranks > 0 then
            local playerInfo = table.takeFirst(ranks)
            self:FreshRankHeadNode(playerInfoTrans, playerInfo, function()
                self:OnRankButtonAction(Constants.TowerType.Blue)
            end)
        end
    end
    if not isUnlock then
        return
    end

    local id = OverseaTowerUtils.GetCurQuestId(Constants.TowerType.Red)
    local vo = OverseaTowerUtils.GetTowerQuestVo(id)
    if vo then
        CfUtils.FillText(self.BtnRedTower.transform:Find("TextNumberShadow"), vo.storey)
        CfUtils.FillText(self.BtnRedTower.transform:Find("TextNumber"), vo.storey)
    end

    local id = OverseaTowerUtils.GetCurQuestId(Constants.TowerType.Green)
    local vo = OverseaTowerUtils.GetTowerQuestVo(id)
    if vo then
        CfUtils.FillText(self.BtnGreenTower.transform:Find("TextNumberShadow"), vo.storey)
        CfUtils.FillText(self.BtnGreenTower.transform:Find("TextNumber"), vo.storey)
    end

    local id = OverseaTowerUtils.GetCurQuestId(Constants.TowerType.Blue)
    local vo = OverseaTowerUtils.GetTowerQuestVo(id)
    if vo then
        CfUtils.FillText(self.BtnBlueTower.transform:Find("TextNumberShadow"), vo.storey)
        CfUtils.FillText(self.BtnBlueTower.transform:Find("TextNumber"), vo.storey)
    end
end

