function UIOverseaTowerEntryDialog:FreshRankHeadNode(headNode, playerInfo, cb)
    ---@type UIActionPromptUpItemNode
    local scr = CfUtils.GetLuaScr(headNode, "Game.UI.FightReady.UIMainChapter.UIActionPromptUpItemNode")
    if scr then
        scr:Refresh(playerInfo.name, false)
    else
        CfUtils.FillText(headNode:Find("Mask/TextName"), playerInfo.name)
    end
    local playerHeadNode = headNode:Find("CommonPlayerHeadNode")
    self:FreshAvatarFrame(playerHeadNode.gameObject, playerInfo, cb)
end

function UIOverseaTowerEntryDialog:FreshAvatarFrame(gameObject, info, cb)
    local PlayerHeadNodePath = "Game.Behaviours.CommonPlayerHeadNode"
    ---@type CommonPlayerHeadNode
    local env = CfUtils.GetLuaScr(gameObject, PlayerHeadNodePath)
    if not isNull(env) then
        env:SetCallBack(function()
            ---头像的点击跳转事件
            if cb then
                cb()
            end
        end)
    end
    env:FreshAvatarFrame(info.avatar, info.avatarFrame)
end

function UIOverseaTowerEntryDialog:OnShow()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        local params = self.controller.Argument.parameters
        if isNotNull(params) and isNotNull(params.jumpTargetId) then
            self:JumpToSubDialog(params.jumpTargetId)
        end
        self.isPlaying = true
        self.position = 1
        ---建立页面轮播机制
        self.controller:StartCoroutine(util.cs_generator(function()
            while self.isPlaying do
                if self.ranks then
                    coroutine.yield(Yielders.GetWaitForSeconds(2))
                    if Utils.TouchCount() <= 0 then
                        self.RankListShow:MovePanelToItemIndex(self.position - 1)
                        self.position = self.position + 1
                        if self.position > #self.ranks then
                            self.position = 1
                        end
                    end
                else
                    coroutine.yield()
                end
            end
        end))
    end))
    return coWait
end

