function UIOverseaTowerEntryDialog:OnInitialize()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        TowerQuestComponent:OverseaClimbingTowerHomeReq(function()
            self:InitData()
            self:FillSelf()
            local hasEntry = KCookie.Get(Constants.UICacheDataKeys.OVERSEA_TOWER_ANIM_CONTROL)
            if hasEntry then
                ---表示打开过弹出的收集页面
                KCookie.RemoveAllListener(Constants.UICacheDataKeys.OVERSEA_TOWER_ANIM_CONTROL)
                --CfUtils.PlayAnimation(self.Root.gameObject, "OverseaTowerEntryDialog_Idle")
                --CfUtils.PlayAnimation(self.BgNode.gameObject, "OverseaTowerEntryDialog_BgNode_Idle")
                --else
                --    CfUtils.PlayAnimation(self.Root.gameObject, "OverseaTowerEntryDialog_Entry")
                --    CfUtils.PlayAnimation(self.BgNode.gameObject, "OverseaTowerEntryDialog_BgNode_Entry")
            end
        end)
    end))
    return coWait
end

function UIOverseaTowerEntryDialog:OnFinalize()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        self.isPlaying = false
        if not isNull(self._timeDown) then
            CDTimerModule.GetInstance():RemoveCD(self._timeDown)
            self._timeDown = nil
        end
        self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
        self:Delete()
        self = nil --lua层的gc需要
    end))
    return coWait
end

function UIOverseaTowerEntryDialog:JumpToSubDialog(jumpTargetId)
    if isNotNull(jumpTargetId) and jumpTargetId > 0 then
        local uiArgs
        if 1 <= jumpTargetId and jumpTargetId <= 4 then
            uiArgs = UIArgs(Constants.UITypeIds.UIOverseaTowerInsideDialog, { type = jumpTargetId })
        elseif jumpTargetId == 100 then
            uiArgs = UIArgs(Constants.UITypeIds.UIOverseaTowerCollectPopup)
        end
        CoStart(function()
            CoYield(0.6)
            self.controller.Argument.parameters.jumpTargetId = nil  -- 跳转以后，清除跳转目标，防止back按钮回来以后又跳过去
            ---@type Engine.UI.UIRaycastBlocker
            local blocker = CS.Engine.UI.UIRaycastBlocker.Instance
            UIModule.OpenDialog(uiArgs, { { id = Constants.UITypeIds.UIOverseaTowerEntryDialog } })
            blocker:RemoveCondition("JumpBlocker")
        end)
    end
end

return UIOverseaTowerEntryDialog
